 */
public void write(char[] chars, int offset, int size) throws IOException {
    test();
    int i = 0;
    int last = offset;
    boolean quoted = false, shouldBeQuoted = false;

    for ( ; i < size; ) {
        char c = chars[i++];

        // A (double) quote character in a field must be represented
